SAFE_HREF = re.compile(r"^(https?://|mailto:|tel:)[^\s\"'<>]+$", re.IGNORECASE)


def esc(text: str) -> str:
    return html.escape(text or "", quote=True)


def icon(kind: str) -> str:
    """Inline SVG icon (decorative, hidden from assistive tech)."""
    return (f'<svg class="ico ico-{kind}" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'
            f'<path d="{ICONS[kind]}"/></svg>')


def rich(text: str, keywords: list[str] | None) -> str:
    """Escape text and wrap **marked** or keyword chunks in <strong>."""
    return "".join(f"<strong>{esc(c)}</strong>" if b else esc(c) for c, b in segments(text, keywords))


def display_case(text: str) -> str:
    """'WORK EXPERIENCE' -> 'Work Experience' so templates can choose their own casing via CSS."""
    if text and text.isascii() and text.isupper() and len(text) > 3:
        small = {"and", "of", "the", "in", "for", "&"}
        return " ".join(w.lower() if w.lower() in small and i else w.capitalize() for i, w in enumerate(text.split()))
    return text


def initials(name: str) -> str:
    parts = [p for p in re.split(r"\s+", name.strip()) if p]
    return "".join(p[0] for p in parts[:2]).upper() if parts else ""


def _link(href: str, text: str) -> str:
    if href and SAFE_HREF.match(href):
        return f'<a href="{esc(href)}">{esc(text)}</a>'
    return f"<span>{esc(text)}</span>"


def render_contacts(contacts: list[dict]) -> str:
    items = "".join(f'<li class="ct ct-{c["kind"]}">{icon(c["kind"])}{_link(c["href"], c["text"])}</li>'
                    for c in contacts)
    return f'<ul class="contacts">{items}</ul>' if items else ""


def render_entry(e: dict, kw) -> str:
    title = esc(e["title"])
    meta = f'<span class="e-meta">{esc(e["meta"])}</span>' if e["meta"] else ""
    parts = ['<article class="entry">']
    if title or meta or e["date"]:
        date = f'<span class="e-date">{icon("calendar")}<span>{esc(e["date"])}</span></span>' if e["date"] else ""
        parts.append(f'<div class="e-row e-row1"><h3 class="e-title"><span class="e-name">{title}</span>{meta}</h3>{date}</div>')
    if e["subtitle"] or e["location"]:
        sub = f'<span class="e-sub">{esc(e["subtitle"])}</span>' if e["subtitle"] else '<span class="e-sub"></span>'
        loc = f'<span class="e-loc">{icon("location")}<span>{esc(e["location"])}</span></span>' if e["location"] else ""
        parts.append(f'<div class="e-row e-row2">{sub}{loc}</div>')
    parts += [f'<p class="e-detail">{rich(d, kw)}</p>' for d in e["details"]]
    if e["bullets"]:
        parts.append('<ul class="e-bullets">' + "".join(f"<li>{rich(b, kw)}</li>" for b in e["bullets"]) + "</ul>")
    if e["tech"]:
        parts.append(f'<p class="e-tech"><strong>{esc(e["tech"]["label"])}:</strong> '
                     f'<em>{esc(e["tech"]["value"])}</em></p>')
    if e["link"]:
        parts.append(f'<p class="e-link">{_link(e["link"], e["link"])}</p>')
    parts.append("</article>")
    return "".join(parts)


def render_skills(groups: list[dict]) -> str:
    out = ['<div class="skills">']
    for g in groups:
        label = f'<h3 class="sk-label">{esc(g["label"])}</h3>' if g["label"] else ""
        items = '<span class="sk-sep">, </span>'.join(f'<span class="sk">{esc(i)}</span>' for i in g["items"])
        out.append(f'<div class="sk-group{" sk-nolabel" if not g["label"] else ""}">{label}<p class="sk-items">{items}</p></div>')
    out.append("</div>")
    return "".join(out)


def render_section(sec: dict, kw) -> str:
    heading = display_case(sec.get("heading") or "")
    body = ""
    if sec["kind"] == "entries":
        body = "".join(render_entry(e, kw) for e in sec["entries"])
    elif sec["kind"] == "skills":
        body = render_skills(sec["groups"])
    elif sec["kind"] == "list":
        body = '<ul class="e-bullets">' + "".join(f"<li>{rich(i, kw)}</li>" for i in sec["items"]) + "</ul>"
    else:
        body = "".join(f'<p class="para">{rich(p, kw)}</p>' for p in sec["paragraphs"])
    title = f'<h2 class="sec-title"><span>{esc(heading)}</span></h2>' if heading else ""
    return f'<section class="sec sec-{sec["key"]} kind-{sec["kind"]}">{title}{body}</section>'


def render_html(text: str, template: str = "modern", accent: str | None = None, bold_keywords: bool = False,
                job_description: str = "", for_pdf: bool = False, lang: str | None = None) -> str:
    """Build the full HTML document for a resume."""
    tpl, accent_name, _ = resolve(template, accent)
    model = build_model(text)
    lang = lang or detect_language(text)
    kw = bold_keywords_for(text, job_description) if bold_keywords else None
    name = display_case(model["name"]) or "Resume"
    avatar = f'<div class="avatar" aria-hidden="true">{esc(initials(name))}</div>' if tpl.get("avatar") else ""
    headline = f'<p class="headline">{esc(model["headline"])}</p>' if model["headline"] else ""
    contacts = render_contacts(model["contacts"])
    layout = tpl["layout"]

    main_secs, side_secs = [], []
    for sec in model["sections"]:
        to_side = layout != "single" and (sec["key"] in SIDEBAR_KEYS or (sec["kind"] in ("skills", "list")))
        (side_secs if to_side else main_secs).append(render_section(sec, kw))

    name_block = f'<div class="hdr-text"><h1 class="name">{esc(name)}</h1>{headline}'
    if layout == "sidebar-left":
        header = f'<header class="hdr">{name_block}</div></header>'
        side_top = f'{avatar}<div class="side-contacts">{contacts}</div>'
        body = (f'<div class="cols"><aside class="col-side">{side_top}{"".join(side_secs)}</aside>'
                f'<main class="col-main">{header}{"".join(main_secs)}</main></div>')
    else:
        header = f'<header class="hdr">{name_block}{contacts}</div>{avatar}</header>'
        if layout == "sidebar-right":
            body = (f'{header}<div class="cols"><main class="col-main">{"".join(main_secs)}</main>'
                    f'<aside class="col-side">{"".join(side_secs)}</aside></div>')
        else:
            body = f'{header}<main class="col-main">{"".join(main_secs)}</main>'

    if for_pdf:
        css = f"<style>{CSS_PATH.read_text(encoding='utf-8-sig')}{PAGE_CSS.get(template, '')}</style>"
        csp = ("<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; "
               "style-src 'unsafe-inline'; img-src data:\">")
    else:
        css = '<link rel="stylesheet" href="/static/resume.css">'
        csp = ""
    direction = "rtl" if lang == "ar" else "ltr"
    classes = f"t-{template if template in _known() else 'modern'} acc-{accent_name} layout-{layout}"
    mode = "pdf" if for_pdf else "screen"
    return (f'<!DOCTYPE html><html lang="{esc(lang)}" dir="{direction}" class="{classes} mode-{mode}">'
            f'<head><meta charset="utf-8">{csp}<title>{esc(name)}</title>{css}</head>'
            f'<body><div class="page">{body}</div></body></html>')


def _known() -> set[str]:
    from .resume_templates import TEMPLATES
    return set(TEMPLATES)
